import math


def get_sieve_of_eratosthenes(n):
    if not isinstance(n, int):
        raise TypeError('n is int type.')
    if n < 2:
        raise ValueError('n is more than 2')
    prime_num = []
    bound = math.sqrt(n)
    data = []
    for i in range(1, n):
        data.append(1 + i)
    while True:
        p = data[0]
        if bound <= p:
            return prime_num + data
        prime_num.append(p)
        data = [e for e in data if 0 != e % p]
    return data

