def irohas_obsession(N: int, K: int, D: list) -> int:
    # D に含まれない最小の値
    min_not_d_val = min(d for d in range(10) if d not in D)
    min_not_d_and_not_zero_value = min(d for d in range(10) if d not in D and 0 != d)

    # 数字を各桁に分解する。
    numbers = []
    while N > 0:
        numbers = [N % 10] + numbers
        N //= 10

    # 上位の桁から見ていって最初に D に含まれる数字を探す。
    convert_idx = -1
    for i, n in enumerate(numbers):
        if n not in D:
            # 変換の必要がない
            continue
        else:

            convert_idx = i
            break
    # print(convert_idx)
    for i in range(convert_idx, -1, -1):
        n = numbers[i]
        if 9 < n:
            n = n % 10
            if i > 0:
                numbers[i - 1] += 1
            else:
                numbers = [min_not_d_and_not_zero_value] + numbers

        for d in range(n, 10):
            # 変換先が n 以上 9 以下
            if d in D:
                # NG
                continue

            numbers[i] = d
            break
        else:
            # 変換先が n 未満
            for d in range(n, 10):
                if d in D:
                    # NG
                    continue

                numbers[i] = d

            # 上位の桁に繰り上がりを伝搬
            if 0 < i:
                numbers[i - 1] += 1
            else:
                numbers = [min_not_d_and_not_zero_value] + numbers

    # 残りの桁は D に含まれない最小の値に変換する。
    numbers = [min_not_d_val if n in D else n for n in numbers]

    retval = 0
    digit = 1
    # print(nums)
    for n in reversed(numbers):
        retval += n * digit
        digit *= 10

    return retval


if "__main__" == __name__:
    N, K = map(int, input().split())
    D = []
    for s in input().split():
        D.append(int(s))
    result = irohas_obsession(N, K, D)
    print(result)
